import json
def read_v2(raw):
    try:value=json.loads(raw)
    except (ValueError,TypeError) as error:raise ValueError('invalid JSON event') from error
    if not isinstance(value,dict):raise ValueError('event must be an object')
    if not isinstance(value.get('id'),str) or not value['id']:raise ValueError('id required')
    if type(value.get('amount_cents')) is not int or value['amount_cents']<0:raise ValueError('nonnegative integer amount required')
    if value.get('kind') not in ('created','cancelled'):raise ValueError('unknown enum is incompatible with v1')
    priority=value.get('priority',0)
    if type(priority) is not int or not 0<=priority<=9:raise ValueError('priority absent defaults0; null/type/range invalid')
    return {'id':value['id'],'amount_cents':value['amount_cents'],'kind':value['kind'],'priority':priority}
def write_v2(value):
    normalized=read_v2(json.dumps(value))
    return json.dumps(normalized,sort_keys=True,separators=(',',':')).encode('utf8')
